    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sentValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sentValue)); require(sentValue <= 1000000000000000000000000000000);
        require(address(this).balance >= sentValue);

        bool ok;
        c.play{value: sentValue}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ok = false;
        } else {
            ok = true;
        }

        assert(ok == (sentValue == 10));
    }

    receive() external payable {}
}

